const mongoose = require('mongoose');

const teacherSchema = new mongoose.Schema({
  // Auto-generated by the controller (TCH001, TCH002 ...). Always stored uppercase so
  // "Tch001" and "TCH001" can never exist side by side.
  teacherId: { type: String, unique: true, uppercase: true, trim: true },
  name: { type: String, required: true, trim: true },
  photo: { type: String },
  gender: { type: String, enum: ['Male','Female','Other'] },
  dateOfBirth: { type: Date },
  phone: { type: String, required: true, trim: true },
  email: { type: String, required: true, unique: true, lowercase: true, trim: true },
  address: { type: String },
  qualification: { type: String },
  experience: { type: Number, min: 0 },
  joiningDate: { type: Date },
  department: { type: String },
  // The form sends subject NAMES ("English", "Physics") — these used to be ObjectIds,
  // which made every save with a subject selected fail.
  subjects: [{ type: String, trim: true }],
  assignedClasses: [{ type: mongoose.Schema.Types.ObjectId, ref: 'Class' }],
  salary: { type: Number, min: 0 },
  bankDetails: {
    accountNumber: String,
    bankName: String,
    ifscCode: String
  },
  // Were missing from the schema, so Mongoose silently dropped them on every save
  rating: { type: Number, min: 0, max: 5, default: 0 },
  description: { type: String, trim: true, maxlength: 500 },
  documents: [{
    type: { type: String },
    name: String,
    fileName: String,
    fileType: String,
    file: String,     // data URL from the Add/Edit form
    fileUrl: String,  // used by POST /api/teachers/:id/documents
    uploadedAt: { type: Date, default: Date.now }
  }],
  userId: { type: mongoose.Schema.Types.ObjectId, ref: 'User' },
  schoolId: { type: mongoose.Schema.Types.ObjectId, ref: 'School' },
  isActive: { type: Boolean, default: true }
}, { timestamps: true });

teacherSchema.index({ name: 'text', teacherId: 'text', email: 'text' });

module.exports = mongoose.model('Teacher', teacherSchema);